import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import './editWarehouseOrderForm.css';

function EditWarehouseOrderForm({addWarehouseOrder}) {
  const [statusnr, setStatusnr] = useState("");
  const [deliverydate, setDeliverydate] = useState("");
  const [statuses, setStatuses] = useState([]);

  const { ordernr } = useParams(); // <--- Vi använder ordernr från URL
  const navigate = useNavigate();

  const token = localStorage.getItem("access_token");

  // Hämta nuvarande data för ordern
  useEffect(() => {
    const fetchOrder = async () => {
      try {
        const response = await fetch(`http://localhost:8080/warehouse-editorder/${ordernr}`, {
          headers: { "Authorization": `Bearer ${token}` },
        });

        if (!response.ok) throw new Error("Kunde inte hämta order");

        const data = await response.json();
        setStatusnr(data.statusnr);
        setDeliverydate(data.deliverydate ? data.deliverydate.substring(0, 16) : ""); // Format för datetime-local
      } catch (error) {
        console.error("Fel vid hämtning av order:", error);
        alert("Kunde inte hämta orderdata.");
      }
    };

    fetchOrder();
  }, [ordernr, token]);

  // Hämta tillgängliga statusar
  useEffect(() => {
    const fetchStatuses = async () => {
      try {
        const res = await fetch("http://localhost:8080/statuses", {
          headers: { "Authorization": `Bearer ${token}` }
        });
        const data = await res.json();
        setStatuses(data);
      } catch (error) {
        console.error("Kunde inte hämta statusar:", error);
      }
    };

    fetchStatuses();
  }, [token]);

  const handleSubmit = async (e) => {
    e.preventDefault();

    const updatedOrder = {
      statusnr: parseInt(statusnr, 10),
      deliverydate: deliverydate || null,
    };

    try {
      const response = await fetch(`http://localhost:8080/warehouse-orders/${ordernr}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`,
        },
        body: JSON.stringify(updatedOrder),
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(errorText || `Status: ${response.status}`);
      }

      alert("Order uppdaterad!");
      navigate("/warehouse-orders");
    } catch (error) {
      console.error("Fel vid uppdatering:", error);
      alert("Kunde inte uppdatera order: " + error.message);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <h1>Edit Warehouse Order</h1>

      <div className="formField">
        <label>Status:</label>
        <select
          value={statusnr}
          onChange={(e) => setStatusnr(e.target.value)}
          required
          className='shortInputField'
        >
          <option value="">Välj status</option>
          {statuses.map((s) => (
            <option key={s.statusnr} value={s.statusnr}>
              {s.statusname}
            </option>
          ))}
        </select>
      </div>

      <div className="formField">
        <label>Delivery Date:</label>
        <input
          type="datetime-local"
          value={deliverydate}
          onChange={(e) => setDeliverydate(e.target.value)}
          className='shortInputField'
        />
      </div>

      <button type="submit" className="addBtn">Update Order</button>
    </form>
  );
}

export default EditWarehouseOrderForm;
